package com.yeyamo_mobile.api.booking_service.infrastructure.outbox;import java.time.Instant;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.booking_service.application.port.BookingOutboxPort;
@Component public class JpaBookingOutboxAdapter implements BookingOutboxPort{private final BookingOutboxRepository repo;private final ObjectMapper mapper;private final String bookingTopic;private final String paymentTopic;public JpaBookingOutboxAdapter(BookingOutboxRepository r,ObjectMapper m,@Value("${yeyamo.kafka.topics.booking-events:booking.events}")String booking,@Value("${yeyamo.kafka.topics.payment-commands:payment.commands}")String payment){repo=r;mapper=m;bookingTopic=booking;paymentTopic=payment;}public void append(String topic,String type,String aggregate,String correlation,Map<String,Object>payload){try{UUID id=UUID.randomUUID();Instant now=Instant.now();Map<String,Object>event=new LinkedHashMap<>();event.put("eventId",id);event.put("eventType",type);event.put("eventVersion",1);event.put("occurredAt",now);event.put("producer","booking-service");event.put("aggregateId",aggregate);event.put("correlationId",correlation==null?id.toString():correlation);event.put("payload",payload);var e=new BookingOutboxEvent();e.id=id;e.aggregateId=aggregate;e.eventType=type;e.targetTopic="booking.events".equals(topic)?bookingTopic:"payment.commands".equals(topic)?paymentTopic:topic;e.payload=mapper.writeValueAsString(event);e.occurredAt=now;repo.save(e);}catch(Exception e){throw new IllegalStateException("Cannot create booking outbox event",e);}}}
